Definition UBL_STACK : Z := 80 + KCMP_STACK.

Definition ubl_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (h : Z) (S : list Z) (ns : NS) (em : gmap Z elt) (r lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz r) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ ATreeR m' h S ns em /\ ACONST m'.

Definition ubl_stmt : Prop := forall (x y kv kp : Z) (k : list byte) (h : Z) (S : list Z) (ns : NS) (em : gmap Z elt)
    (fuel : nat) (r lo : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  ATreeR m h S ns em -> (x = 0 \/ x ∈ S) -> 0 <= y < 2^64 ->
  rw_cells asegs m kv [C8 (wz kp); C8 (wz (zlength k))] -> bytes_at asegs m kp k ->
  upper_bound_loop fuel (cmpU key_lt (key_of em) (zbytes k)) ns x y = Some r ->
  stk asegs m lo (bv_unsigned sp) -> lo + UBL_STACK <= bv_unsigned sp -> aceil <= lo ->       (* [comment removed for export] *)
  (kv + 16 <= lo \/ bv_unsigned sp <= kv) ->
  (kp + zlength k <= lo \/ bv_unsigned sp <= kp) ->
  mem_inv asegs m ->
  (* [comment removed for export] *)
  kv mod 8 = 0 -> accessible m kv 16 -> accessible m kp (zlength k) -> ACONST m ->
  evt asegs (ubl_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc h S ns em r lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz x) (wz y) (wz kv) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_RB_UPPER_BOUND_LOOP) fc None m (seg_rom asegs)).

