Section BL.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (m : mem) (kv kp : Z) (k : list byte) (h : Z) (S : list Z) (ns : NS) (em : gmap Z elt) (lo : Z).

  Definition bl_ctx (m1 : mem) (j16 : list byte) : Prop :=
    rw_cells asegs m1 (bv_unsigned sp + -80) [CB 16 j16; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]
    /\ stk asegs m1 lo (bv_unsigned sp + -80)
    /\ ATreeR m1 h S ns em
    /\ rw_cells asegs m1 kv [C8 (wz kp); C8 (wz (zlength k))] /\ bytes_at asegs m1 kp k
    /\ accessible m1 kv 16 /\ accessible m1 kp (zlength k) /\ ACONST m1
    /\ munch [(lo, bv_unsigned sp)]%Z m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1.

  (* [comment removed for export] *)
  Lemma bl_ctx_frame : forall m1 m2 j16 lo',
    ATreeR m1 h S ns em -> accessible m1 kv 16 -> accessible m1 kp (zlength k) ->
    munch [(lo, lo')]%Z m1 m2 -> wmono asegs m1 m2 -> aceil <= lo -> 
    rw_cells asegs m2 (bv_unsigned sp + -80) [CB 16 j16; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
    stk asegs m2 lo (bv_unsigned sp + -80) ->
    rw_cells asegs m2 kv [C8 (wz kp); C8 (wz (zlength k))] -> bytes_at asegs m2 kp k -> ACONST m2 ->
    munch [(lo, bv_unsigned sp)]%Z m m2 -> wmono asegs m m2 -> mem_inv asegs m2 ->
    bl_ctx m2 j16.
  Proof.
    intros m1 m2 j16 lo' TR KVA KPA MUc WMc CE FR ST KV KB AC MU WM MI.
    assert (SW : stackW lo' [(lo, lo')]) by (apply stackW_one; lia).
    split; [exact FR|]. split; [exact ST|].
    split; [eapply ATreeR_transport; [exact TR| exact MUc| exact WMc| exact SW]|].
    split; [exact KV|]. split; [exact KB|].
    split; [eapply accessible_transport_awin; [exact KVA| exact MUc| exact (stackW_awin _ _ SW)]|].
    split; [eapply accessible_transport_awin; [exact KPA| exact MUc| exact (stackW_awin _ _ SW)]|].
    split; [exact AC|]. split; [exact MU|]. split; [exact WM| exact MI].
  Qed.
End BL.

